int findNearestIndex(List<double> list, double target, int startIndex) {
  int nearestIndex = -1;
  double minDifference = double.infinity;

  for (int i = 0; i < list.length; i++) {
    if (i == startIndex) continue;

    double diff = abs(list[i] - target);

    if (diff < minDifference) {
      minDifference = diff;
      nearestIndex = i;
    } else if (diff == minDifference) {
      // If there's a tie, choose the first occurrence
      if (i < nearestIndex) {
        nearestIndex = i;
      }
    }
  }

  return nearestIndex;
}

