import 'dart:math';

int carRaceCollision(int n) {
  if (n < 2) return 0;

  final List<int> dp = [0, 1]; // dp[0] unused, dp[1] = 0 collisions for 1 car

  for (var i = 2; i <= n; i++) {
    int totalCollisions = 0;

    // For each position j where a collision can happen with the previous cars
    for (var j = 1; j < i; j++) {
      var leftCars = j; 
      var rightCars = i - j;

      // The number of ways to arrange the cars so that a collision happens at this split
      var waysToSplit = combinations(i-1, j);

      // Calculate collisions from both sides and add them
      totalCollisions += waysToSplit * ((leftCars * (leftCars + 1)) ~/ 2 + (rightCars * (rightCars + 1)) ~/ 2); 
    }

    dp.add(totalCollisions);
  }

  return dp[n];
}

// Helper function to calculate combination(n, k)
int combinations(int n, int k) {
  if (k > n || k < 0) return 0;
  if (k == 0 || k == n) return 1;
  k = min(k, n - k);
  var result = 1;
  for (var i = 1; i <= k; i++) {
    result *= (n - i + 1) / i;
  }
  return result;
}
