String _cleanInput(String input) {
  var chars = <String>[];
  for (var i = 0; i < input.length; ++i) {
    if (_isAlphanumeric(input[i])) {
      chars.add(input[i].toLowerCase());
    }
  }
  return chars.join();
}

bool _isAlphanumeric(String char) {
  int codeUnit = char.codeUnitsFirst;
  bool isLetter = (codeUnit >= 65 && codeUnit <= 90) || (codeUnit >= 97 && codeUnit <= 122);
  bool isDigit = codeUnit >= 48 && codeUnit <= 57;
  return isLetter || isDigit;
}

bool _checkPalindrome(String s, int left, int right) {
  if (left >= right) return true;
  if (s[left] != s[right]) return false;
  return _checkPalindrome(s, left + 1, right - 1);
}

