  int totalFruits = appleCount + orangeCount;

  // Check if there are enough fruits to distribute
  if (totalFruits < n) {
    return -1; // Not enough fruits available
  }

  // Distribute fruits based on priority: apples first
  int distributedApples = min(appleCount, n);
  int remainingFruits = n - distributedApples;
  int distributedOranges = min(orangeCount, remainingFruits);

  return distributedApples + distributedOranges;
}

