          nextNonZero = j;
          break;
        }
      }

      if (nextNonZero != -1) {
        newPositions.add(arr[nextNonZero]); 
        moved = true;
        i = nextNonZero; // Skip over the element we just added
      }
    }
  }

  // Add the remaining elements after the last zero
  while (zeroIndex < arr.length) {
    if (arr[zeroIndex] != 0) {
      newPositions.add(arr[zeroIndex]);
    }
    zeroIndex++;
  }

  arr.clear();
  arr.addAll(newPositions);
  return moved;
