int maxFill(List<List<int>> grid, int capacity) {
  if (grid == null || grid.isEmpty || grid[0].isEmpty) return 0;

  final rows = grid.length;
  final cols = grid[0].length;
  final totalCapacity = rows * cols * capacity;

  var currentFill = 0;

  for (var i = 0; i < rows; i++) {
    for (var j = 0; j < cols; j++) {
      // Calculate the fill needed to reach full
      var fillNeeded = (capacity - grid[i][j]);

      // If we can't fill this cell without exceeding capacity, skip it
      if (fillNeeded <= 0) continue;

      // Check if there's enough remaining space in the container
      if (currentFill + fillNeeded > totalCapacity) break;

      currentFill += fillNeeded;
    }
  }

  return currentFill;
}

