import 'dart:collection';

bool isSorted(List<int> lst) {
  if (lst.isEmpty || lst.length == 1) return true;

  final queue = Queue<int>();
  for (int i = 0; i < lst.length - 1; i++) {
    queue.add(lst[i]);
  }

  int current = lst[0];
  while (!queue.isEmpty) {
    final next = queue.removeFirst();

    if (next > current) return false;
    current = next;
  }

  return true;
}

