        if (j != n - 1) {
          temp.add(grid[i][j + 1]);
        }

        if (temp.isNotEmpty) {
          val = temp.reduce((a, b) => a < b ? a : b);
        }
      }
    }
  }

  List<int> ans = [];
  for (int i = 0; i < k; i++) {
    if (i % 2 == 0) {
      ans.add(1);
    } else {
      ans.add(val);
    }
  }

  return ans;
}

