bool isNested(String string) {
  if (string == null || string.isEmpty) return false;

  int depth = 0;
  for (int i = 0; i < string.length; i++) {
    final char = string[i];

    // Increment depth on opening bracket
    if (char == '(' || char == '[' || char == '{') {
      depth++;

      // Check if the current character is a closing bracket and we have at least one open bracket before it
      if (depth > 1 && !isClosingBracket(char)) {
        continue;
      }
    } else if (char == ')' || char == ']' || char == '}') {
      // If there's no matching opening bracket, it's invalid
      if (depth <= 0) {
        return false;
      }
      depth--;
    }
  }

  // Return true only if all brackets are properly closed
  return depth == 0;
}

