  int totalA = counts[0], totalB = counts[1];

  // Calculate the number of valid substrings
  int result = 0;

  // Count all substrings with more a's than b's.
  // For each position where we can split into two parts:
  for (int i = 0; i <= totalA + totalB - 1; ++i) {
    int countA = 0, countB = 0;

    // Traverse from left to right and track balance
    int balance = 0;
    for (int j = 0; j <= i; ++j) {
      if (s[j] == 'a') {
        countA++;
        balance += 1;
      } else {
        countB++;
        balance -= 1;
      }

      // If at any point balance is positive, it means there are more a's up to this index
      if (balance > 0) {
        result += countA - countB; // add all possible substrings ending here with more a's
      }
    }
  }

  return "$result";
}

