String solve(String s) {
  int n = s.length;
  if (n == 0) return '';

  List<int> count = List.filled(26, 0);
  for (int i=0; i < n; ++i) {
    count[s[i].codeUnitAt(0) - 'a'.codeUnitAt(0)] += 1;
  }

  String result = '';
  bool allEven = true;
  for (var c in count) {
    if (c % 2 != 0) {
      allEven = false;
    }
  }

  if (allEven) {
    // All characters have even counts
    return 'YES';
  } else {
    int oddCount = 0;
    int firstOddIndex = -1;
    for (int i=0; i<26; ++i) {
      if (count[i] % 2 != 0) {
        oddCount++;
        firstOddIndex = i;
      }
    }

    if (oddCount > 2 || oddCount == 1) {
      return 'NO';
    }

    if (oddCount == 1 && firstOddIndex == 0) {
      return 'NO'; // Only one character with odd count and it's the first letter
    }

    // Check if we can rearrange to make palindrome by moving one of two odds
    int left = 0;
    int right = n-1;
    while (left < right) {
      if (s[left] != s[right]) {
        break;
      }
      left++;
      right--;
    }

    if (left >= right) {
      return 'YES';
    }

    int swapChar = 0;
    int swapsNeeded = 0;
    for (int j = 0; j <= left; ++j) {
      if (s[j] != s[n-1-j]) {
        swapChar = s[j];
        swapsNeeded += 1;
        break;
      }
    }

    if (swapsNeeded == 0) {
      return 'YES';
    }

    if (swapChar != s[n-1-left]) {
      return 'NO';
    }

    return 'YES';
  }
}

String solve(String s) {
