      count++;
    }
  }

  String res = '';
  for (int j = 0; j < s.length - count + 1; j++) {
    bool valid = true;
    for (int k = j; k < j + count; k++) {
      if (!(s[k] >= 'a' && s[k] <= 'z') && !(s[k] >= 'A' && s[k] <= 'Z')) {
        valid = false;
        break;
      }
    }
    if (valid) {
      res += s[j];
    } else {
      res += '_';
    }
  }

  return res;
}

